async function (vars) {
    vars.TransactionSourceSystemResult = (await getSystem({ Id: vars.TransactionSourceSystemId })).value;
},
async function (vars) {
    if (vars.TransactionSourceSystemResult.length === 0) {
        vars.TransactionSourceSystem = await createSystem({
            Id: vars.TransactionSourceSystemId,
            Name: vars.TransactionSourceSystemId,
            Description: "Transaction Source System for " + vars.AppName + "." + vars.AppType,
            IsPublic: false
        });
    } else {
        vars.TransactionSourceSystem = vars.TransactionSourceSystemResult[0];
    }
}
